  }

  * { box-sizing: border-box; }

  html, body {
    margin: 0;
    padding: 0;
    background: var(--bg);
    color: var(--text);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    min-height: 100vh;
  }

  .app {
    max-width: 560px;
    margin: 60px auto;
    padding: 0 20px;
  }

  h1 {
    text-align: center;
    font-size: 2.5rem;
    margin: 0 0 24px;
    color: var(--text);
    letter-spacing: -0.5px;
