</style>
</head>
<body>
  <div class="app">
    <h1>📝 Todo</h1>
    <div class="card">
      <div class="input-row">
        <input id="todo-input" type="text" placeholder="What needs to be done?" maxlength="200" />
        <button id="add-btn" class="btn btn-primary">Add</button>
      </div>

      <div class="filters" id="filters">
        <button class="filter-btn active" data-filter="all">All</button>
        <button class="filter-btn" data-filter="active">Active</button>
        <button class="filter-btn" data-filter="completed">Completed</button>
      </div>

      <ul id="todo-list" class="todo-list"></ul>

      <div class="footer">
        <span id="counter">0 items left</span>
        <button id="clear-btn" class="clear-btn">Clear completed</button>
      </div>
    </div>
  </div>

<script>
(function () {
  'use strict';

  const STORAGE_KEY = 'todos_app_v1';
  const FILTER_KEY = 'todos_filter_v1';

  /** @type {{id:number,text:string,done:boolean}[]} */
  let todos = loadTodos();
  let filter = loadFilter();

  const $input = document.getElementById('todo-input');
  const $addBtn = document.getElementById('add-btn');
  const $list = document.getElementById('todo-list');
  const $filters = document.getElementById('filters');
  const $counter = document.getElementById('counter');
  const $clearBtn = document.getElementById('clear-btn');

  // ---- persistence ----
  function loadTodos() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(t => t && typeof t.text === 'string').map(t => ({
        id: Number(t.id) || Date.now() + Math.random(),
        text: String(t.text),
        done: Boolean(t.done)
      }));
    } catch (e) {
      return [];
    }
  }

  function saveTodos() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      console.error('Failed to save todos', e);
    }
  }

  function loadFilter() {
    const v = localStorage.getItem(FILTER_KEY);
    return (v === 'active' || v === 'completed') ? v : 'all';
  }

  function saveFilter() {
    try { localStorage.setItem(FILTER_KEY, filter); } catch (e) {}
  }

  // ---- actions ----
  function addTodo(text) {
    const trimmed = text.trim();
    if (!trimmed) return;
    todos.push({
      id: Date.now() + Math.floor(Math.random() * 1000),
      text: trimmed,
      done: false
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    const t = todos.find(x => x.id === id);
    if (!t) return;
    t.done = !t.done;
    saveTodos();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(x => x.id !== id);
    saveTodos();
    render();
  }

  function clearCompleted() {
    const before = todos.length;
    todos = todos.filter(t => !t.done);
    if (todos.length !== before) {
      saveTodos();
      render();
    }
  }

  function setFilter(f) {
    if (f !== 'all' && f !== 'active' && f !== 'completed') return;
    filter = f;
    saveFilter();
    render();
  }

  // ---- rendering ----
  function getVisible() {
    if (filter === 'active') return todos.filter(t => !t.done);
    if (filter === 'completed') return todos.filter(t => t.done);
    return todos;
  }

  function render() {
    // filter buttons
    Array.from($filters.querySelectorAll('.filter-btn')).forEach(btn => {
      btn.classList.toggle('active', btn.dataset.filter === filter);
    });

    // list
    const visible = getVisible();
    $list.innerHTML = '';

    if (visible.length === 0) {
      const li = document.createElement('li');
      li.className = 'empty';
      li.textContent = todos.length === 0
        ? 'No todos yet — add one above!'
        : 'Nothing here.';
      $list.appendChild(li);
    } else {
      const frag = document.createDocumentFragment();
      visible.forEach(t => {
        const li = document.createElement('li');
        li.className = 'todo-item' + (t.done ? ' done' : '');
        li.dataset.id = String(t.id);

        const cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.checked = t.done;
        cb.setAttribute('aria-label', 'Mark complete');
        cb.addEventListener('change', () => toggleTodo(t.id));

        const span = document.createElement('span');
        span.className = 'todo-text';
        span.textContent = t.text;

        const del = document.createElement('button');
        del.className = 'delete-btn';
        del.setAttribute('aria-label', 'Delete todo');
        del.title = 'Delete';
        del.textContent = '✕';
        del.addEventListener('click', () => deleteTodo(t.id));

        li.appendChild(cb);
        li.appendChild(span);
        li.appendChild(del);
        frag.appendChild(li);
      });
      $list.appendChild(frag);
    }

    // counter
    const left = todos.filter(t => !t.done).length;
    $counter.textContent = left + (left === 1 ? ' item left' : ' items left');

    // clear button
    const hasCompleted = todos.some(t => t.done);
    $clearBtn.disabled = !hasCompleted;
  }

  // ---- events ----
  $addBtn.addEventListener('click', () => {
    addTodo($input.value);
    $input.value = '';
    $input.focus();
  });

  $input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      addTodo($input.value);
      $input.value = '';
    }
  });

  $filters.addEventListener('click', (e) => {
    const btn = e.target.closest('.filter-btn');
    if (!btn) return;
    setFilter(btn.dataset.filter);
  });

  $clearBtn.addEventListener('click', clearCompleted);

  // initial paint
  render();
  $input.focus();
})();
</script>
</body>
</html>
